mod palette;
mod room;
mod connector;

pub(super) fn plugin(app: &mut App) {
    app.add_plugins((connector::plugin, palette::plugin, room::plugin));
}

#[derive(Debug)]
pub enum MapType {
    Main,
    Boss,
    Side,
}

#[derive(Debug)]
pub struct MapDefinition {
    palette: Palette,
    map_type: MapType,
}

impl MapDefinition {
    pub fn bake(&self, seed: u64, rand: impl Rng) -> MapState {
        todo!()
    }
}

#[derive(Component, Debug)]
pub struct MapState {
    grid: Entity,
    injectable: RoomDefinition,
}

pub fn map_state(
    grid: Entity,
    injectable: RoomDefinition,
) -> impl Bundle {
    MapState {
        grid,
        injectable,
    }
}

